                JsonSerializer.Serialize(writer, creditInput.Specifiers, jsonSerializerOptions);
            }
            if (creditInput.NetsuiteSalesOrderIdOption.IsSet)
                writer.WriteString("netsuite_sales_order_id", creditInput.NetsuiteSalesOrderId);

            if (creditInput.PriorityOption.IsSet)
                writer.WriteNumber("priority", creditInput.PriorityOption.Value!.Value);

            if (creditInput.CustomFieldsOption.IsSet)
            {
                writer.WritePropertyName("custom_fields");
                JsonSerializer.Serialize(writer, creditInput.CustomFields, jsonSerializerOptions);
            }
            if (creditInput.RolloverFractionOption.IsSet)
                writer.WriteNumber("rollover_fraction", creditInput.RolloverFractionOption.Value!.Value);

            var rateTypeRawValue = CreditInput.RateTypeEnumToJsonValue(creditInput.RateTypeOption.Value!.Value);
            writer.WriteString("rate_type", rateTypeRawValue);
            if (creditInput.HierarchyConfigurationOption.IsSet)
            {
                writer.WritePropertyName("hierarchy_configuration");
                JsonSerializer.Serialize(writer, creditInput.HierarchyConfiguration, jsonSerializerOptions);
            }
        }
    }
}
